```c
switch (sigpending) {
case 1:
    if (likely(get_ucounts(ucounts)))
        break;
fallthrough;
case LONG_MAX:
    dec_rlimit_ucounts(ucounts, UCOUNT_RLIMIT_SIGPENDING, 1);
    rcu_read_unlock();
    return NULL;
}
```
